# Adaptive rejection sampling (Gilks and Wild, 1992)
# The target function may be an unnormalised density, but must return
# positive finite values and be log-concave on the supplied interval.

.ars_validate_density <- function(density_function, domain, n) {
  if (!is.function(density_function))
    stop("density_function must be a function")
  if (!is.numeric(domain) || length(domain) != 2L || any(!is.finite(domain)) ||
      domain[1L] >= domain[2L])
    stop("domain must be a finite numeric vector c(lower, upper), with lower < upper")
  if (!is.numeric(n) || length(n) != 1L || !is.finite(n) || n < 0 || n != as.integer(n))
    stop("n must be one non-negative integer")
  invisible(TRUE)
}

.ars_eval_log_density <- function(f, x) {
  y <- tryCatch(f(x), error = function(e) stop("density_function failed: ", e$message))
  if (length(y) == 1L && length(x) > 1L) y <- rep(y, length(x))
  if (length(y) != length(x)) stop("density_function must be vectorized and return one value per x")
  if (any(!is.finite(y)) || any(y <= 0))
    stop("density_function must return finite, strictly positive values on the sampled domain")
  log(y)
}

# A grid check catches obvious violations before sampling. Local checks below
# also catch violations among every triple of active support points.
.ars_check_log_concavity <- function(f, domain, grid_n = 101L, tolerance = 1e-7) {
  x <- seq(domain[1L], domain[2L], length.out = grid_n)
  z <- .ars_eval_log_density(f, x)
  d2 <- z[-c(1L, 2L)] - 2 * z[-c(1L, length(z))] + z[-c(length(z)-1L, length(z))]
  if (any(d2 > tolerance * (1 + abs(z[-c(1L, 2L)]))))
    stop("density appears non-log-concave on the supplied domain")
  invisible(TRUE)
}

.ars_slopes <- function(x, h) {
  n <- length(x)
  if (n == 2L) return(c((h[2L] - h[1L])/(x[2L] - x[1L]),
                         (h[2L] - h[1L])/(x[2L] - x[1L])))
  s <- diff(h) / diff(x)
  c(s[1L], (s[-1L] * diff(x)[-1L] + s[-length(s)] * diff(x)[-length(s)]) /
      (diff(x)[-1L] + diff(x)[-length(s)]), s[length(s)])
}

.ars_intersections <- function(x, h, slope) {
  n <- length(x)
  z <- numeric(n - 1L)
  for (i in seq_len(n - 1L)) {
    den <- slope[i + 1L] - slope[i]
    if (abs(den) < 1e-12) z[i] <- (x[i] + x[i + 1L]) / 2
    else z[i] <- (h[i + 1L] - slope[i + 1L] * x[i + 1L] - h[i] + slope[i] * x[i]) / den
    z[i] <- max(x[i], min(x[i + 1L], z[i]))
  }
  c(x[1L], z, x[n])
}

.ars_interval_mass <- function(a, b, m, c) {
  # Integral exp(m*x+c) dx, evaluated stably around the midpoint.
  mid <- (a + b) / 2
  w <- exp(m * mid + c)
  if (abs(m) < 1e-10) w * (b - a) else w * 2 * sinh(m * (b - a) / 2) / m
}

.ars_draw_from_interval <- function(a, b, m, c) {
  u <- runif(1L)
  if (abs(m) < 1e-10) return(a + u * (b - a))
  # Inverse CDF using a scaled exponential expression, avoiding overflow.
  a + log1p(u * expm1(m * (b - a))) / m
}

.ars_hull <- function(x, h) {
  slope <- .ars_slopes(x, h)
  z <- .ars_intersections(x, h, slope)
  # Upper hull on interval [z[i], z[i+1]] uses tangent at x[i].
  cval <- h - slope * x
  mass <- vapply(seq_len(length(x) - 1L), function(i)
    .ars_interval_mass(z[i], z[i + 1L], slope[i], cval[i]), numeric(1L))
  if (any(!is.finite(mass)) || any(mass <= 0)) stop("failed to construct a finite ARS envelope")
  list(slope = slope, intercept = cval, z = z, mass = mass)
}

.ars_propose <- function(hull) {
  p <- hull$mass / sum(hull$mass)
  i <- sample.int(length(p), 1L, prob = p)
  list(x = .ars_draw_from_interval(hull$z[i], hull$z[i + 1L],
                                   hull$slope[i], hull$intercept[i]), i = i)
}

# Adaptive rejection sampler. For finite domains the initial support is at both
# endpoints plus an interior point. The implementation uses tangent upper hulls
# and squeeze/rejection tests, adding accepted points to adapt the hull.
ars <- function(density_function, domain, n = sample_count) {
  .ars_validate_density(density_function, domain, n)
  n <- as.integer(n)
  if (n == 0L) return(numeric(0L))
  .ars_check_log_concavity(density_function, domain)
  lo <- domain[1L]; hi <- domain[2L]
  x <- c(lo, (lo + hi) / 2, hi)
  h <- .ars_eval_log_density(density_function, x)
  if (any(diff(h) == 0)) warning("flat portions detected; continuing with ARS")
  out <- numeric(n); accepted <- 0L; attempts <- 0L
  while (accepted < n) {
    if (attempts > max(10000L, 1000L * n)) stop("ARS acceptance is too low; check density and domain")
    hull <- .ars_hull(x, h)
    q <- .ars_propose(hull); y <- q$x
    hy <- .ars_eval_log_density(density_function, y)[1L]
    upper <- hull$slope[q$i] * y + hull$intercept[q$i]
    if (hy > upper + 1e-7) stop("non-log-concave density detected during sampling")
    attempts <- attempts + 1L
    if (log(runif(1L)) <= hy - upper) {
      accepted <- accepted + 1L; out[accepted] <- y
      if (all(abs(x - y) > 1e-10)) {
        k <- order(c(x, y)); xx <- c(x, y); hh <- c(h, hy)
        x <- xx[k]; h <- hh[k]
      }
    } else if (all(abs(x - y) > 1e-10)) {
      k <- order(c(x, y)); xx <- c(x, y); hh <- c(h, hy)
      x <- xx[k]; h <- hh[k]
    }
  }
  out
}

.print_test <- function(name, ok, values = numeric(0L), target = NA_real_) {
  if (length(values)) {
    cat(sprintf("%s: %s (mean=%.4f, sd=%.4f", name, if (ok) "PASS" else "FAIL",
                mean(values), sd(values)))
    if (is.finite(target)) cat(sprintf(", target=%.4f", target))
    cat(")\n")
  } else cat(sprintf("%s: %s\n", name, if (ok) "PASS" else "FAIL"))
  invisible(ok)
}

# Formal stochastic tests against known moments and input/error behavior.
test <- function() {
  set.seed(2024)
  normal <- ars(function(x) dnorm(x), c(-8, 8), 3000)
  exponential <- ars(function(x) dexp(x), c(0, 25), 3000)
  ok1 <- abs(mean(normal)) < 0.10 && abs(sd(normal) - 1) < 0.10
  ok2 <- abs(mean(exponential) - 1) < 0.08 && abs(sd(exponential) - 1) < 0.08
  bad <- tryCatch({ ars(function(x) 1 + 0.8 * sin(x), c(0, 2*pi), 10); FALSE }, error = function(e) TRUE)
  invalid <- tryCatch({ ars(function(x) dnorm(x), c(1, 0), 2); FALSE }, error = function(e) TRUE)
  .print_test("NORMAL_MOMENTS", ok1, normal, 0)
  .print_test("EXPONENTIAL_MOMENTS", ok2, exponential, 1)
  .print_test("NON_LOG_CONCAVE_REJECTION", bad)
  .print_test("INVALID_DOMAIN_REJECTION", invalid)
  write.table(normal, "/app/normal_samples.txt", row.names = FALSE, col.names = FALSE)
  all_ok <- ok1 && ok2 && bad && invalid
  cat(sprintf("ALL_TESTS: %s\n", if (all_ok) "PASS" else "FAIL"))
  invisible(all_ok)
}
EOF
