cat > /app/ars.R <<'EOF'
# Adaptive rejection sampler based on Gilks, Wild (1992).
# The target may be unnormalised, but must be positive and log-concave.

.ars_validate <- function(density_function, domain, n) {
  if (!is.function(density_function)) stop("density_function must be a function")
  if (!is.numeric(domain) || length(domain) != 2L || any(!is.finite(domain)) || domain[1] >= domain[2])
    stop("domain must be finite c(lower, upper), with lower < upper")
  if (!is.numeric(n) || length(n) != 1L || !is.finite(n) || n < 0 || n != floor(n))
    stop("n must be one non-negative integer")
  invisible(TRUE)
}

.ars_log_density <- function(f, x) {
  y <- tryCatch(f(x), error = function(e) stop("density_function error: ", e$message))
  if (length(y) == 1L && length(x) > 1L) y <- rep(y, length(x))
  if (length(y) != length(x)) stop("density_function must be vectorized")
  if (any(!is.finite(y)) || any(y <= 0))
    stop("density_function must return finite positive values on the domain")
  log(y)
}

.ars_check_concavity <- function(f, domain, grid_n = 201L, tol = 1e-7) {
  x <- seq(domain[1], domain[2], length.out = grid_n)
  h <- .ars_log_density(f, x)
  # For equally spaced points, concavity means every second difference <= 0.
  d2 <- h[-c(1, 2)] - 2 * h[-c(1, length(h))] + h[-c(length(h)-1, length(h))]
  scale <- 1 + abs(h[-c(1, 2)]) + 2 * abs(h[-c(1, length(h))]) + abs(h[-c(length(h)-1, length(h))])
  if (any(d2 > tol * scale)) stop("density appears non-log-concave on the supplied domain")
  invisible(TRUE)
}

.ars_slopes <- function(x, h) {
  sec <- diff(h) / diff(x)
  if (length(sec) == 1L) return(rep(sec, 2L))
  # Interior derivative estimates are weighted averages of adjacent secants.
  interior <- (sec[-length(sec)] * diff(x)[-length(sec)] +
               sec[-1L] * diff(x)[-1L]) /
              (diff(x)[-length(sec)] + diff(x)[-1L])
  c(sec[1L], interior, sec[length(sec)])
}

.ars_hull <- function(x, h) {
  slope <- .ars_slopes(x, h)
  k <- length(x)
  z <- numeric(k + 1L)
  z[1L] <- x[1L]; z[k + 1L] <- x[k]
  for (i in seq_len(k - 1L)) {
    den <- slope[i + 1L] - slope[i]
    if (abs(den) < 1e-12) val <- (x[i] + x[i + 1L]) / 2
    else val <- (h[i + 1L] - slope[i + 1L] * x[i + 1L] - h[i] + slope[i] * x[i]) / den
    z[i + 1L] <- max(x[i], min(x[i + 1L], val))
  }
  intercept <- h - slope * x
  list(x = x, h = h, slope = slope, intercept = intercept, z = z)
}

.ars_mass <- function(a, b, m, c) {
  mid <- (a + b) / 2
  if (abs(m) < 1e-10) return(exp(m * mid + c) * (b - a))
  # midpoint form is substantially more stable than exp(c)*(exp(mb)-exp(ma)).
  exp(m * mid + c) * (2 * sinh(m * (b - a) / 2) / m)
}

.ars_hull_masses <- function(hull) {
  k <- length(hull$x)
  mass <- vapply(seq_len(k), function(i)
    .ars_mass(hull$z[i], hull$z[i + 1L], hull$slope[i], hull$intercept[i]), numeric(1))
  if (any(!is.finite(mass)) || any(mass <= 0)) stop("could not construct a finite ARS envelope")
  mass
}

.ars_propose <- function(hull, mass) {
  i <- sample.int(length(mass), 1L, prob = mass / sum(mass))
  a <- hull$z[i]; b <- hull$z[i + 1L]; m <- hull$slope[i]
  if (abs(m) < 1e-10) y <- a + runif(1L) * (b - a)
  else y <- a + log1p(runif(1L) * expm1(m * (b - a))) / m
  list(y = min(max(y, a), b), i = i)
}

.ars_insert <- function(x, h, y, hy) {
  if (any(abs(x - y) < 1e-12)) return(list(x = x, h = h))
  o <- order(c(x, y))
  xx <- c(x, y); hh <- c(h, hy)
  list(x = xx[o], h = hh[o])
}

ars <- function(density_function, domain, n = sample_count) {
  .ars_validate(density_function, domain, n)
  n <- as.integer(n)
  if (n == 0L) return(numeric(0L))
  .ars_check_concavity(density_function, domain)
  lo <- domain[1L]; hi <- domain[2L]
  x <- c(lo, (lo + hi) / 2, hi)
  h <- .ars_log_density(density_function, x)
  ans <- numeric(n); got <- 0L; attempts <- 0L
  while (got < n) {
    attempts <- attempts + 1L
    if (attempts > max(10000L, 2000L * n)) stop("ARS acceptance rate is too low")
    hull <- .ars_hull(x, h)
    mass <- .ars_hull_masses(hull)
    prop <- .ars_propose(hull, mass)
    y <- prop$y
    hy <- .ars_log_density(density_function, y)
    upper <- hull$slope[prop$i] * y + hull$intercept[prop$i]
    # This is an online safety check for non-log-concavity.
    if (hy > upper + 1e-6) stop("non-log-concave density detected during sampling")
    # Rejection from the tangent envelope; adding every proposal adapts the hull.
    accept <- log(runif(1L)) <= hy - upper
    if (accept) {
      got <- got + 1L
      ans[got] <- y
    }
    ins <- .ars_insert(x, h, y, hy)
    x <- ins$x; h <- ins$h
  }
  ans
}

.ars_report <- function(name, ok, z, target = NA_real_) {
  if (length(z)) {
    extra <- if (is.finite(target)) sprintf(", target=%.4f", target) else ""
    cat(sprintf("%s: %s (mean=%.4f, sd=%.4f%s)\n", name,
                if (ok) "PASS" else "FAIL", mean(z), sd(z), extra))
  } else cat(sprintf("%s: %s\n", name, if (ok) "PASS" else "FAIL"))
  invisible(ok)
}

test <- function() {
  set.seed(202503)
  normal <- ars(function(x) dnorm(x), c(-8, 8), n = 3000)
  exponential <- ars(function(x) dexp(x), c(0, 25), n = 3000)
  normal_ok <- abs(mean(normal)) < .10 && abs(sd(normal) - 1) < .10
  exponential_ok <- abs(mean(exponential) - 1) < .08 && abs(sd(exponential) - 1) < .08
  nonconcave_ok <- tryCatch({ ars(function(x) 1 + .8 * sin(x), c(0, 2*pi), 10); FALSE }, error = function(e) TRUE)
  invalid_ok <- tryCatch({ ars(dnorm, c(2, 1), 2); FALSE }, error = function(e) TRUE)
  .ars_report("NORMAL_MOMENTS", normal_ok, normal, 0)
  .ars_report("EXPONENTIAL_MOMENTS", exponential_ok, exponential, 1)
  .ars_report("NON_LOG_CONCAVE_REJECTION", nonconcave_ok, numeric(0))
  .ars_report("INVALID_DOMAIN_REJECTION", invalid_ok, numeric(0))
  write.table(normal, "/app/normal_samples.txt", row.names = FALSE, col.names = FALSE)
  all_ok <- normal_ok && exponential_ok && nonconcave_ok && invalid_ok
  cat(sprintf("ALL_TESTS: %s\n", if (all_ok) "PASS" else "FAIL"))
  invisible(all_ok)
}
EOF
