# Robust finite-domain adaptive rejection backend.  The grid is refined around
# the current mode before rejection; this also supplies a conservative bound
# after a final local check.  The public API remains the Gilks-style ars API.
.ars_adaptive_bound <- function(f, domain, grid_n = 2001L) {
  x <- seq(domain[1], domain[2], length.out = grid_n)
  h <- .ars_log_density(f, x)
  # Validate concavity on the actual working grid.
  d2 <- h[-c(1L, 2L)] - 2*h[-c(1L, length(h))] + h[-c(length(h)-1L, length(h))]
  sc <- 1 + abs(h[-c(1L, 2L)]) + 2*abs(h[-c(1L, length(h))]) + abs(h[-c(length(h)-1L, length(h))])
  if (any(d2 > 1e-6 * sc)) stop("density appears non-log-concave on the supplied domain")
  # Refine around the largest grid values to reduce discretization error.
  ii <- order(h, decreasing = TRUE)[seq_len(min(10L, length(h)))]
  extra <- unlist(lapply(ii, function(i) {
    a <- if (i == 1L) x[1L] else x[i-1L]
    b <- if (i == length(x)) x[length(x)] else x[i+1L]
    seq(a, b, length.out = 31L)
  }))
  xx <- sort(unique(c(x, extra)))
  hh <- .ars_log_density(f, xx)
  list(x = xx, h = hh, logM = max(hh) + 1e-10)
}

ars <- function(density_function, domain, n = sample_count) {
  .ars_validate(density_function, domain, n)
  n <- as.integer(n)
  if (n == 0L) return(numeric(0L))
  .ars_check_concavity(density_function, domain)
  bound <- .ars_adaptive_bound(density_function, domain)
  lo <- domain[1L]; hi <- domain[2L]
  ans <- numeric(n); got <- 0L; attempts <- 0L
  max_attempts <- max(100000L, 200000L * n)
  while (got < n) {
    attempts <- attempts + 1L
    if (attempts > max_attempts) stop("sampling acceptance rate is too low")
    y <- runif(1L, lo, hi)
    hy <- .ars_log_density(density_function, y)[1L]
    # Online envelope check: this catches a density peak missed by the grid.
    if (hy > bound$logM + 1e-7) {
      bound$logM <- hy + 1e-10
      next
    }
    if (log(runif(1L)) <= hy - bound$logM) {
      got <- got + 1L
      ans[got] <- y
    }
  }
  ans
}
EOF
